with open('telugu_panchangam/eclipses.py', 'r') as f:
    content = f.read()

content = content.replace("def get_eclipse_for_date(d: date, loc: Location) -> Optional[EclipseResult]:", "from functools import lru_cache\n\n@lru_cache(maxsize=128)\ndef _cached_eclipse_for_date(d_iso: str, loc_lat: float, loc_lon: float, loc_tz: str) -> Optional[EclipseResult]:\n    d = date.fromisoformat(d_iso)\n    loc = Location(name='', lat=loc_lat, lon=loc_lon, timezone=loc_tz)\n    geopos = [loc.lon, loc.lat, 0.0]\n    jd_midnight = local_midnight_jd(d, loc.timezone)\n    \n    def finder(jd, coords):\n        # check solar\n        if swe_solar := _solar_eclipse(jd):\n            kind, subtype, visible = 'Solar', swe_solar[2], False\n            if _solar_visible(jd - 2, jd + 2, loc):\n                visible = True\n            return EclipseResult(\n                kind=kind, subtype=subtype, visible=visible,\n                start=jd_to_utc(swe_solar[0]), end=jd_to_utc(swe_solar[1]),\n                sutak_start=None, sutak_end=None\n            )\n        if swe_lunar := _lunar_eclipse(jd):\n            return EclipseResult(\n                kind='Lunar', subtype=swe_lunar[2], visible=True,\n                start=jd_to_utc(swe_lunar[0]), end=jd_to_utc(swe_lunar[1]),\n                sutak_start=None, sutak_end=None\n            )\n        return None\n\n    return finder(jd_midnight, geopos)\n\ndef get_eclipse_for_date(d: date, loc: Location) -> Optional[EclipseResult]:\n    return _cached_eclipse_for_date(d.isoformat(), loc.lat, loc.lon, loc.timezone)")

with open('telugu_panchangam/eclipses.py', 'w') as f:
    f.write(content)
